  readonly x: number;
  readonly y: number;
  readonly z: number;
  /** The face normal at the contact, in world axes. */
  readonly nx: number;
  readonly ny: number;
  readonly nz: number;
  /** How far along the ray the contact lies, in world units. */
  readonly distance: number;
  /** The entity or player id, or "" when the contact is terrain. */
  readonly id: string;
