        npc,
        hp: ZOMBIE_MAX_HP,
        lastAttackAt: 0,
        state: "wander",
        ownerDid: "",
        wanderHeading: 0,
        wanderUntil: 0,
        lastBroadcastAt: getNow(),
        cellKey: key,
        homeX: pose.x,
        homeZ: pose.z,
